        if (diff !== null) return diff;
        diff = _tryMergeBaseDiff(cmd, baseBranch, headBranch);
        if (diff !== null) return diff;

        console.error('All diff strategies failed for', baseBranch, '...', headBranch);
        return '';
    } catch (e) {
        console.error('Failed to get PR diff:', e);
        return '';
    }
